@page "/settings"
@using sv_a0749a6edf9f4e6f8e9b23f51a159490.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")"
                    @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Value.Icon</span>
                    <span class="nav-label">@section.Value.Label</span>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="toast @_toastType">
                <span>@_toastMessage</span>
                <button class="toast-close" @onclick="DismissToast">&times;</button>
            </div>
        }

        @if (ActiveSection == "profile")
        {
            <section class="settings-section">
                <h2>Profile</h2>
                @if (_profile is not null)
                {
                    <div class="profile-form">
                        <div class="avatar-area">
                            <div class="avatar-preview">
                                @if (!string.IsNullOrEmpty(_editProfile_AvatarUrl))
                                {
                                    <img src="@_editProfile_AvatarUrl" alt="Avatar" />
                                }
                                else
                                {
                                    <div class="avatar-placeholder">No Avatar</div>
                                }
                            </div>
                            <span class="avatar-url-display">@_editProfile_AvatarUrl</span>
                        </div>

                        <div class="form-group">
                            <label for="displayName">Display Name</label>
                            <input id="displayName" type="text" @bind="_editProfile_DisplayName" />
                        </div>

                        <div class="form-group">
                            <label for="email">Email</label>
                            <input id="email" type="email" @bind="_editProfile_Email" />
                        </div>

                        <div class="form-group">
                            <label for="bio">Bio</label>
                            <textarea id="bio" rows="4" @bind="_editProfile_Bio"></textarea>
                        </div>

                        <div class="form-actions">
                            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                            <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                        </div>
                    </div>
                }
                else
                {
                    <p>Loading profile...</p>
                }
            </section>
        }
        else if (ActiveSection == "notifications")
        {
            <section class="settings-section">
                <h2>Notifications</h2>
                @if (_notifications is not null)
                {
                    <div class="notification-form">
                        <div class="toggle-group">
                            <label class="toggle-label">
                                <input type="checkbox" @bind="_editNotif_Email" />
                                <span class="toggle-switch"></span>
                                <span>Email Notifications</span>
                            </label>
                        </div>

                        <div class="toggle-group">
                            <label class="toggle-label">
                                <input type="checkbox" @bind="_editNotif_Push" />
                                <span class="toggle-switch"></span>
                                <span>Push Notifications</span>
                            </label>
                        </div>

                        <div class="toggle-group">
                            <label class="toggle-label">
                                <input type="checkbox" @bind="_editNotif_WeeklyDigest" />
                                <span class="toggle-switch"></span>
                                <span>Weekly Digest</span>
                            </label>
                        </div>

                        <h3>Muted Channels</h3>
                        <div class="channels-list">
                            @foreach (var channel in _allChannels)
                            {
                                <label class="channel-item">
                                    <input type="checkbox"
                                           checked="@_editNotif_MutedChannels.Contains(channel)"
                                           @onchange="e => ToggleMutedChannel(channel, (bool)e.Value!)" />
                                    <span>@channel</span>
                                </label>
                            }
                        </div>

                        <div class="form-actions">
                            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                        </div>
                    </div>
                }
                else
                {
                    <p>Loading notification preferences...</p>
                }
            </section>
        }
        else if (ActiveSection == "security")
        {
            <section class="settings-section">
                <h2>Security</h2>
                @if (_security is not null)
                {
                    <div class="security-form">
                        <!-- Change Password Panel -->
                        <div class="expandable-panel">
                            <button class="panel-header" @onclick="() => _passwordPanelExpanded = !_passwordPanelExpanded">
                                <span>Change Password</span>
                                <span class="expand-icon">@(_passwordPanelExpanded ? "▾" : "▸")</span>
                            </button>
                            @if (_passwordPanelExpanded)
                            {
                                <div class="panel-body">
                                    <div class="form-group">
                                        <label for="currentPassword">Current Password</label>
                                        <input id="currentPassword" type="password" @bind="_currentPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="newPassword">New Password</label>
                                        <input id="newPassword" type="password" @bind="_newPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="confirmPassword">Confirm Password</label>
                                        <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                                    </div>
                                    @if (!string.IsNullOrEmpty(_passwordError))
                                    {
                                        <p class="error-text">@_passwordError</p>
                                    }
                                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                                </div>
                            }
                        </div>

                        <!-- Two-Factor Authentication -->
                        <div class="two-factor-section">
                            <h3>Two-Factor Authentication</h3>
                            <div class="status-row">
                                <span class="status-indicator @(_security.TwoFactorEnabled ? "status-enabled" : "status-disabled")"></span>
                                <span>@(_security.TwoFactorEnabled ? "Enabled" : "Disabled")</span>
                            </div>
                        </div>

                        <!-- Active Sessions -->
                        <div class="sessions-section">
                            <h3>Active Sessions</h3>
                            <table class="sessions-table">
                                <thead>
                                    <tr>
                                        <th>Device</th>
                                        <th>Location</th>
                                        <th>Last Active</th>
                                        <th></th>
                                    </tr>
                                </thead>
                                <tbody>
                                    @foreach (var session in _security.Sessions)
                                    {
                                        <tr>
                                            <td>@session.Device</td>
                                            <td>@session.Location</td>
                                            <td>@session.LastActive.ToString("g")</td>
                                            <td>
                                                @if (session.Id != _currentSessionId)
                                                {
                                                    <button class="btn btn-danger btn-sm"
                                                            @onclick="() => ConfirmRevokeSession(session)">
                                                        Revoke
                                                    </button>
                                                }
                                                else
                                                {
                                                    <span class="current-badge">Current</span>
                                                }
                                            </td>
                                        </tr>
                                    }
                                </tbody>
                            </table>
                        </div>

                        <!-- Revoke Confirmation Dialog -->
                        @if (_sessionToRevoke is not null)
                        {
                            <div class="dialog-overlay" @onclick="CancelRevoke">
                                <div class="dialog" @onclick:stopPropagation="true">
                                    <h4>Revoke Session</h4>
                                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
                                    <div class="dialog-actions">
                                        <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>
                }
                else
                {
                    <p>Loading security settings...</p>
                }
            </section>
        }
        else if (ActiveSection == "appearance")
        {
            <section class="settings-section">
                <h2>Appearance</h2>
                @if (_appearance is not null)
                {
                    <div class="appearance-form">
                        <!-- Theme -->
                        <div class="form-group">
                            <label>Theme</label>
                            <div class="radio-group">
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="Light"
                                           checked="@(_editAppearance_Theme == "Light")"
                                           @onchange='() => _editAppearance_Theme = "Light"' />
                                    <span>Light</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="Dark"
                                           checked="@(_editAppearance_Theme == "Dark")"
                                           @onchange='() => _editAppearance_Theme = "Dark"' />
                                    <span>Dark</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="System"
                                           checked="@(_editAppearance_Theme == "System")"
                                           @onchange='() => _editAppearance_Theme = "System"' />
                                    <span>System</span>
                                </label>
                            </div>
                        </div>

                        <!-- Font Size -->
                        <div class="form-group">
                            <label>Font Size</label>
                            <div class="radio-group">
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Small"
                                           checked="@(_editAppearance_FontSize == "Small")"
                                           @onchange='() => _editAppearance_FontSize = "Small"' />
                                    <span>Small</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Medium"
                                           checked="@(_editAppearance_FontSize == "Medium")"
                                           @onchange='() => _editAppearance_FontSize = "Medium"' />
                                    <span>Medium</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Large"
                                           checked="@(_editAppearance_FontSize == "Large")"
                                           @onchange='() => _editAppearance_FontSize = "Large"' />
                                    <span>Large</span>
                                </label>
                            </div>
                        </div>

                        <!-- Language -->
                        <div class="form-group">
                            <label for="language">Language</label>
                            <select id="language" @bind="_editAppearance_Language">
                                <option value="en">English</option>
                                <option value="es">Spanish</option>
                                <option value="fr">French</option>
                                <option value="de">German</option>
                                <option value="ja">Japanese</option>
                                <option value="zh">Chinese</option>
                            </select>
                        </div>

                        <!-- Compact Mode -->
                        <div class="toggle-group">
                            <label class="toggle-label">
                                <input type="checkbox" @bind="_editAppearance_CompactMode" />
                                <span class="toggle-switch"></span>
                                <span>Compact Mode</span>
                            </label>
                        </div>

                        <!-- Live Preview -->
                        <div class="preview-area @GetPreviewClasses()">
                            <h4>Live Preview</h4>
                            <p>This is how your content will look with the selected settings.</p>
                            <div class="preview-card">
                                <strong>Sample Card</strong>
                                <p>Here is some example text to demonstrate the appearance settings you've chosen.</p>
                                <button class="btn btn-primary">Sample Button</button>
                            </div>
                        </div>

                        <div class="form-actions">
                            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                        </div>
                    </div>
                }
                else
                {
                    <p>Loading appearance settings...</p>
                }
            </section>
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "profile";

    private record SectionInfo(string Label, string Icon);
    private readonly Dictionary<string, SectionInfo> _sections = new()
    {
        ["profile"] = new("Profile", "👤"),
        ["notifications"] = new("Notifications", "🔔"),
        ["security"] = new("Security", "🔒"),
        ["appearance"] = new("Appearance", "🎨")
    };

    // Toast
    private string _toastMessage = "";
    private string _toastType = "";

    // Profile state
    private UserProfile? _profile;
    private string _editProfile_DisplayName = "";
    private string _editProfile_Email = "";
    private string _editProfile_AvatarUrl = "";
    private string _editProfile_Bio = "";

    // Notification state
    private NotificationPrefs? _notifications;
    private bool _editNotif_Email;
    private bool _editNotif_Push;
    private bool _editNotif_WeeklyDigest;
    private HashSet<string> _editNotif_MutedChannels = new();
    private readonly List<string> _allChannels = new() { "general", "announcements", "engineering", "design", "marketing", "random" };

    // Security state
    private SecuritySettings? _security;
    private bool _passwordPanelExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string _passwordError = "";
    private ActiveSession? _sessionToRevoke;
    private string _currentSessionId = "";

    // Appearance state
    private AppearanceSettings? _appearance;
    private string _editAppearance_Theme = "Light";
    private string _editAppearance_FontSize = "Medium";
    private string _editAppearance_Language = "en";
    private bool _editAppearance_CompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
        await LoadNotifications();
        await LoadSecurity();
        await LoadAppearance();
    }

    // ===== Profile =====
    private async Task LoadProfile()
    {
        _profile = await SettingsService.GetProfileAsync();
        PopulateProfileFields(_profile);
    }

    private void PopulateProfileFields(UserProfile profile)
    {
        _editProfile_DisplayName = profile.DisplayName;
        _editProfile_Email = profile.Email;
        _editProfile_AvatarUrl = profile.AvatarUrl;
        _editProfile_Bio = profile.Bio;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(_editProfile_DisplayName, _editProfile_Email, _editProfile_AvatarUrl, _editProfile_Bio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (_profile is not null)
        {
            PopulateProfileFields(_profile);
        }
    }

    // ===== Notifications =====
    private async Task LoadNotifications()
    {
        _notifications = await SettingsService.GetNotificationPrefsAsync();
        _editNotif_Email = _notifications.EmailNotifications;
        _editNotif_Push = _notifications.PushNotifications;
        _editNotif_WeeklyDigest = _notifications.WeeklyDigest;
        _editNotif_MutedChannels = new HashSet<string>(_notifications.MutedChannels);
    }

    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted)
            _editNotif_MutedChannels.Add(channel);
        else
            _editNotif_MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var updated = new NotificationPrefs(_editNotif_Email, _editNotif_Push, _editNotif_WeeklyDigest, _editNotif_MutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _notifications = updated;
        ShowToast("Notification preferences saved!", "success");
    }

    // ===== Security =====
    private async Task LoadSecurity()
    {
        _security = await SettingsService.GetSecuritySettingsAsync();
        if (_security.Sessions.Count > 0)
        {
            _currentSessionId = _security.Sessions[0].Id;
        }
    }

    private async Task UpdatePassword()
    {
        _passwordError = "";

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "New password is required.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelExpanded = false;
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
            await LoadSecurity();
            ShowToast("Session revoked.", "success");
        }
    }

    // ===== Appearance =====
    private async Task LoadAppearance()
    {
        _appearance = await SettingsService.GetAppearanceAsync();
        _editAppearance_Theme = _appearance.Theme;
        _editAppearance_FontSize = _appearance.FontSize;
        _editAppearance_Language = _appearance.Language;
        _editAppearance_CompactMode = _appearance.CompactMode;
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(_editAppearance_Theme, _editAppearance_FontSize, _editAppearance_Language, _editAppearance_CompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _appearance = updated;
        ShowToast("Appearance settings saved!", "success");
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_editAppearance_Theme.ToLowerInvariant()} preview-font-{_editAppearance_FontSize.ToLowerInvariant()}";
        if (_editAppearance_CompactMode) classes += " preview-compact";
        return classes;
    }

    // ===== Toast =====
    private void ShowToast(string message, string type)
    {
        _toastMessage = message;
        _toastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        _toastMessage = "";
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast()
    {
        _toastMessage = "";
    }
}

