@code {
    private string ActiveSection { get; set; } = "profile";

    private record SectionInfo(string Label, string Icon);
    private readonly Dictionary<string, SectionInfo> _sections = new()
    {
        ["profile"] = new("Profile", "👤"),
        ["notifications"] = new("Notifications", "🔔"),
        ["security"] = new("Security", "🔒"),
        ["appearance"] = new("Appearance", "🎨")
    };

    // Toast
    private string _toastMessage = "";
    private string _toastType = "";

    // Profile state
    private UserProfile? _profile;
    private string _editProfile_DisplayName = "";
    private string _editProfile_Email = "";
    private string _editProfile_AvatarUrl = "";
    private string _editProfile_Bio = "";

    // Notification state
    private NotificationPrefs? _notifications;
    private bool _editNotif_Email;
    private bool _editNotif_Push;
    private bool _editNotif_WeeklyDigest;
    private HashSet<string> _editNotif_MutedChannels = new();
    private readonly List<string> _allChannels = new() { "general", "announcements", "engineering", "design", "marketing", "random" };

    // Security state
    private SecuritySettings? _security;
    private bool _passwordPanelExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string _passwordError = "";
    private ActiveSession? _sessionToRevoke;
    private string _currentSessionId = "";

    // Appearance state
    private AppearanceSettings? _appearance;
    private string _editAppearance_Theme = "Light";
    private string _editAppearance_FontSize = "Medium";
    private string _editAppearance_Language = "en";
    private bool _editAppearance_CompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
        await LoadNotifications();
        await LoadSecurity();
        await LoadAppearance();
    }

    // ===== Profile =====
    private async Task LoadProfile()
    {
        _profile = await SettingsService.GetProfileAsync();
        PopulateProfileFields(_profile);
    }

    private void PopulateProfileFields(UserProfile profile)
    {
        _editProfile_DisplayName = profile.DisplayName;
        _editProfile_Email = profile.Email;
        _editProfile_AvatarUrl = profile.AvatarUrl;
        _editProfile_Bio = profile.Bio;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(_editProfile_DisplayName, _editProfile_Email, _editProfile_AvatarUrl, _editProfile_Bio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (_profile is not null)
        {
            PopulateProfileFields(_profile);
        }
    }

    // ===== Notifications =====
    private async Task LoadNotifications()
    {
        _notifications = await SettingsService.GetNotificationPrefsAsync();
        _editNotif_Email = _notifications.EmailNotifications;
        _editNotif_Push = _notifications.PushNotifications;
        _editNotif_WeeklyDigest = _notifications.WeeklyDigest;
        _editNotif_MutedChannels = new HashSet<string>(_notifications.MutedChannels);
    }

    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted)
            _editNotif_MutedChannels.Add(channel);
        else
            _editNotif_MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var updated = new NotificationPrefs(_editNotif_Email, _editNotif_Push, _editNotif_WeeklyDigest, _editNotif_MutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _notifications = updated;
        ShowToast("Notification preferences saved!", "success");
    }

    // ===== Security =====
    private async Task LoadSecurity()
    {
        _security = await SettingsService.GetSecuritySettingsAsync();
        if (_security.Sessions.Count > 0)
        {
            _currentSessionId = _security.Sessions[0].Id;
        }
    }

    private async Task UpdatePassword()
    {
        _passwordError = "";

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "New password is required.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelExpanded = false;
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
            await LoadSecurity();
            ShowToast("Session revoked.", "success");
        }
    }

    // ===== Appearance =====
    private async Task LoadAppearance()
    {
        _appearance = await SettingsService.GetAppearanceAsync();
        _editAppearance_Theme = _appearance.Theme;
        _editAppearance_FontSize = _appearance.FontSize;
        _editAppearance_Language = _appearance.Language;
        _editAppearance_CompactMode = _appearance.CompactMode;
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(_editAppearance_Theme, _editAppearance_FontSize, _editAppearance_Language, _editAppearance_CompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _appearance = updated;
        ShowToast("Appearance settings saved!", "success");
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_editAppearance_Theme.ToLowerInvariant()} preview-font-{_editAppearance_FontSize.ToLowerInvariant()}";
        if (_editAppearance_CompactMode) classes += " preview-compact";
        return classes;
    }

    // ===== Toast =====
    private void ShowToast(string message, string type)
    {
        _toastMessage = message;
        _toastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        _toastMessage = "";
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast()
    {
        _toastMessage = "";
    }
}

