@page "/settings"
@using sv_a0749a6edf9f4e6f8e9b23f51a159490.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")"
                    @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Value.Icon</span>
                    <span class="nav-label">@section.Value.Label</span>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="toast @_toastType">
                <span>@_toastMessage</span>
                <button class="toast-close" @onclick="DismissToast">&times;</button>
            </div>
        }

        @if (ActiveSection == "profile")
        {
            <section class="settings-section">
                <h2>Profile</h2>
                @if (_profile is not null)
                {
                    <div class="profile-form">
                        <div class="avatar-area">
                            <div class="avatar-preview">
                                @if (!string.IsNullOrEmpty(_editProfile_AvatarUrl))
                                {
                                    <img src="@_editProfile_AvatarUrl" alt="Avatar" />
                                }
                                else
                                {
                                    <div class="avatar-placeholder">No Avatar</div>
                                }
                            </div>
                            <span class="avatar-url-display">@_editProfile_AvatarUrl</span>
                        </div>

                        <div class="form-group">
                            <label for="displayName">Display Name</label>
                            <input id="displayName" type="text" @bind="_editProfile_DisplayName" />
                        </div>

                        <div class="form-group">
                            <label for="email">Email</label>
                            <input id="email" type="email" @bind="_editProfile_Email" />
                        </div>

                        <div class="form-group">
                            <label for="bio">Bio</label>
                            <textarea id="bio" rows="4" @bind="_editProfile_Bio"></textarea>
                        </div>

                        <div class="form-actions">
                            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                            <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                        </div>
                    </div>
                }
                else
                {
                    <p>Loading profile...</p>
                }
            </section>
        }
        else if (ActiveSection == "notifications")
        {
            <section class="settings-section">
                <h2>Notifications</h2>
                @if (_notifications is not null)
                {
                    <div class="notification-form">
                        <div class="toggle-group">
                            <label class="toggle-label">
                                <input type="checkbox" @bind="_editNotif_Email" />
                                <span class="toggle-switch"></span>
                                <span>Email Notifications</span>
                            </label>
                        </div>

                        <div class="toggle-group">
                            <label class="toggle-label">
                                <input type="checkbox" @bind="_editNotif_Push" />
                                <span class="toggle-switch"></span>
                                <span>Push Notifications</span>
                            </label>
                        </div>

                        <div class="toggle-group">
                            <label class="toggle-label">
                                <input type="checkbox" @bind="_editNotif_WeeklyDigest" />
                                <span class="toggle-switch"></span>
                                <span>Weekly Digest</span>
                            </label>
                        </div>

                        <h3>Muted Channels</h3>
                        <div class="channels-list">
                            @foreach (var channel in _allChannels)
                            {
                                <label class="channel-item">
                                    <input type="checkbox"
                                           checked="@_editNotif_MutedChannels.Contains(channel)"
                                           @onchange="e => ToggleMutedChannel(channel, (bool)e.Value!)" />
                                    <span>@channel</span>
                                </label>
                            }
                        </div>

                        <div class="form-actions">
                            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                        </div>
                    </div>
                }
                else
                {
                    <p>Loading notification preferences...</p>
                }
            </section>
        }
        else if (ActiveSection == "security")
        {
            <section class="settings-section">
                <h2>Security</h2>
                @if (_security is not null)
                {
                    <div class="security-form">
                        <!-- Change Password Panel -->
                        <div class="expandable-panel">
                            <button class="panel-header" @onclick="() => _passwordPanelExpanded = !_passwordPanelExpanded">
                                <span>Change Password</span>
                                <span class="expand-icon">@(_passwordPanelExpanded ? "▾" : "▸")</span>
                            </button>
                            @if (_passwordPanelExpanded)
                            {
                                <div class="panel-body">
                                    <div class="form-group">
                                        <label for="currentPassword">Current Password</label>
                                        <input id="currentPassword" type="password" @bind="_currentPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="newPassword">New Password</label>
                                        <input id="newPassword" type="password" @bind="_newPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="confirmPassword">Confirm Password</label>
                                        <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                                    </div>
                                    @if (!string.IsNullOrEmpty(_passwordError))
                                    {
                                        <p class="error-text">@_passwordError</p>
                                    }
                                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                                </div>
                            }
                        </div>

                        <!-- Two-Factor Authentication -->
                        <div class="two-factor-section">
                            <h3>Two-Factor Authentication</h3>
                            <div class="status-row">
                                <span class="status-indicator @(_security.TwoFactorEnabled ? "status-enabled" : "status-disabled")"></span>
                                <span>@(_security.TwoFactorEnabled ? "Enabled" : "Disabled")</span>
                            </div>
                        </div>

                        <!-- Active Sessions -->
                        <div class="sessions-section">
                            <h3>Active Sessions</h3>
                            <table class="sessions-table">
                                <thead>
                                    <tr>
                                        <th>Device</th>
                                        <th>Location</th>
                                        <th>Last Active</th>
                                        <th></th>
                                    </tr>
                                </thead>
                                <tbody>
                                    @foreach (var session in _security.Sessions)
                                    {
                                        <tr>
                                            <td>@session.Device</td>
                                            <td>@session.Location</td>
                                            <td>@session.LastActive.ToString("g")</td>
                                            <td>
                                                @if (session.Id != _currentSessionId)
                                                {
                                                    <button class="btn btn-danger btn-sm"
                                                            @onclick="() => ConfirmRevokeSession(session)">
                                                        Revoke
                                                    </button>
                                                }
                                                else
                                                {
                                                    <span class="current-badge">Current</span>
                                                }
                                            </td>
                                        </tr>
                                    }
                                </tbody>
                            </table>
                        </div>

                        <!-- Revoke Confirmation Dialog -->
                        @if (_sessionToRevoke is not null)
                        {
                            <div class="dialog-overlay" @onclick="CancelRevoke">
                                <div class="dialog" @onclick:stopPropagation="true">
                                    <h4>Revoke Session</h4>
                                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
                                    <div class="dialog-actions">
                                        <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>
                }
                else
                {
                    <p>Loading security settings...</p>
                }
            </section>
        }
        else if (ActiveSection == "appearance")
        {
            <section class="settings-section">
                <h2>Appearance</h2>
                @if (_appearance is not null)
                {
                    <div class="appearance-form">
                        <!-- Theme -->
                        <div class="form-group">
                            <label>Theme</label>
                            <div class="radio-group">
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="Light"
                                           checked="@(_editAppearance_Theme == "Light")"
                                           @onchange='() => _editAppearance_Theme = "Light"' />
                                    <span>Light</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="Dark"
                                           checked="@(_editAppearance_Theme == "Dark")"
                                           @onchange='() => _editAppearance_Theme = "Dark"' />
                                    <span>Dark</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="System"
                                           checked="@(_editAppearance_Theme == "System")"
                                           @onchange='() => _editAppearance_Theme = "System"' />
                                    <span>System</span>
                                </label>
                            </div>
                        </div>

                        <!-- Font Size -->
                        <div class="form-group">
                            <label>Font Size</label>
                            <div class="radio-group">
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Small"
                                           checked="@(_editAppearance_FontSize == "Small")"
                                           @onchange='() => _editAppearance_FontSize = "Small"' />
                                    <span>Small</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Medium"
                                           checked="@(_editAppearance_FontSize == "Medium")"
                                           @onchange='() => _editAppearance_FontSize = "Medium"' />
                                    <span>Medium</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Large"
                                           checked="@(_editAppearance_FontSize == "Large")"
                                           @onchange='() => _editAppearance_FontSize = "Large"' />
                                    <span>Large</span>
                                </label>
                            </div>
                        </div>

                        <!-- Language -->
                        <div class="form-group">
                            <label for="language">Language</label>
                            <select id="language" @bind="_editAppearance_Language">
                                <option value="en">English</option>
                                <option value="es">Spanish</option>
                                <option value="fr">French</option>
                                <option value="de">German</option>
                                <option value="ja">Japanese</option>
                                <option value="zh">Chinese</option>
                            </select>
                        </div>

                        <!-- Compact Mode -->
                        <div class="toggle-group">
                            <label class="toggle-label">
                                <input type="checkbox" @bind="_editAppearance_CompactMode" />
                                <span class="toggle-switch"></span>
                                <span>Compact Mode</span>
                            </label>
                        </div>

                        <!-- Live Preview -->
                        <div class="preview-area @GetPreviewClasses()">
                            <h4>Live Preview</h4>
                            <p>This is how your content will look with the selected settings.</p>
                            <div class="preview-card">
                                <strong>Sample Card</strong>
                                <p>Here is some example text to demonstrate the appearance settings you've chosen.</p>
                                <button class="btn btn-primary">Sample Button</button>
                            </div>
                        </div>

                        <div class="form-actions">
                            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                        </div>
                    </div>
                }
                else
                {
                    <p>Loading appearance settings...</p>
                }
            </section>
        }
    </main>
</div>

